WITH ranked AS (SELECT id, supplier_name FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY city ORDER BY rating NULLS FIRST, id) AS dedup_rank FROM suppliers) ranked WHERE dedup_rank = 1), filtered AS (SELECT *, UPPER(TRIM(supplier_name)) AS supplier_name_normalized FROM ranked WHERE supplier_name NOT LIKE '%Suppl%'), with_latest AS (SELECT s.*, top1.category, top1.launch_date FROM filtered s JOIN LATERAL (SELECT c.category, c.launch_date FROM products c WHERE c.supplier_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) top1 ON TRUE), with_latest_suppliers AS (SELECT s.*, latest.product_cost, latest.product_launch_date FROM with_latest s JOIN LATERAL (SELECT c.cost AS product_cost, c.launch_date AS product_launch_date FROM products c WHERE c.supplier_id = s.id ORDER BY c.cost DESC, c.id DESC LIMIT 1) latest ON TRUE) SELECT CASE WHEN product_cost >= 550 THEN 'HIGH' ELSE 'LOW' END AS product_cost_tier, COUNT(*) FILTER (WHERE category = 'Sports') AS sports_rows, COUNT_IF(category = 'Home') AS home_events, APPROX_PERCENTILE(product_cost, 0.95) AS product_cost_p95, MIN(product_cost) AS min_product_cost, COUNT(DISTINCT category) AS distinct_categories FROM with_latest_suppliers GROUP BY 1 ORDER BY product_cost_p95 DESC;
